  ctx.fillStyle = beam; ctx.beginPath(); ctx.moveTo(wx + ww * 0.2, wy + wh); ctx.lineTo(wx + ww, wy + wh * 0.4); ctx.lineTo(W() * 0.98, H() * 0.7); ctx.lineTo(W() * 0.35, H() * 0.72); ctx.closePath(); ctx.fill();
  ctx.globalCompositeOperation = "source-over"; ctx.globalAlpha = 1;
