    ctx.fillStyle = fill; roundRect(jx + 3, sy - jh * 0.72, jw - 6, jh * 0.72 - 3, 4); ctx.fill();
    ctx.fillStyle = "#7a4a26"; roundRect(jx - 1, sy - jh - 6, jw + 2, 8, 3); ctx.fill();
