  if (!cake.flying) { ctx.fillStyle = "rgba(40,20,5,.25)"; ctx.beginPath(); ctx.ellipse(0, 8, cake.r, cake.r * 0.18, 0, 0, Math.PI * 2); ctx.fill(); }
  const ry = Math.max(3, Math.abs(k) * cake.r * 0.3);
