  x.drawImage(source, 0, 0, w, h);
  const d = x.getImageData(0, 0, w, h).data;
  const px = []; for (let i = 0; i < w * h; i++) px.push([d[i * 4], d[i * 4 + 1], d[i * 4 + 2]]);
  // k-means, seeded by spreading picks across the picture's colours.
  let centres = [px[Math.floor(Math.random() * px.length)]];
  while (centres.length < colours) {
    let best = null, bestD = -1;
    for (let t = 0; t < 400; t++) {
      const p = px[Math.floor(Math.random() * px.length)];
      const dd = Math.min(...centres.map((q) => (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2 + (p[2] - q[2]) ** 2));
      if (dd > bestD) { bestD = dd; best = p; }
    }
    centres.push(best);
  }
  const label = new Uint8Array(px.length);
  for (let iter = 0; iter < 10; iter++) {
    const sum = centres.map(() => [0, 0, 0, 0]);
    px.forEach((p, i) => {
      let bi = 0, bd = Infinity;
      centres.forEach((q, j) => { const dd = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2 + (p[2] - q[2]) ** 2; if (dd < bd) { bd = dd; bi = j; } });
      label[i] = bi; const s = sum[bi]; s[0] += p[0]; s[1] += p[1]; s[2] += p[2]; s[3]++;
    });
    centres = centres.map((q, j) => (sum[j][3] ? [sum[j][0] / sum[j][3], sum[j][1] / sum[j][3], sum[j][2] / sum[j][3]] : q));
  }
  // A square on its own takes its neighbours' colour, so there are fewer one-square specks.
  for (let pass = 0; pass < 2; pass++) for (let y = 0; y < h; y++) for (let xx = 0; xx < w; xx++) {
    const i = y * w + xx, counts = {};
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { const nx = xx + dx, ny = y + dy; if (nx >= 0 && ny >= 0 && nx < w && ny < h) { const l = label[ny * w + nx]; counts[l] = (counts[l] || 0) + 1; } }
    if (!counts[label[i]]) { const top = Object.entries(counts).sort((a, b) => b[1] - a[1])[0]; if (top && top[1] >= 3) label[i] = Number(top[0]); }
  }
  // Number colours light to dark; drop any that ended up unused.
  const used = [...new Set(label)];
  const order = used.sort((a, b) => { const L = (q) => 0.299 * q[0] + 0.587 * q[1] + 0.114 * q[2]; return L(centres[b]) - L(centres[a]); });
